import java.util.ArrayList;
import java.util.List;

public class NameCleanerSorter {

    /**
     * Cleans and sorts an array of names.
     *
     * Cleaning steps:
     *  - Removes all non-alphabetic characters (digits, symbols, spaces, etc.)
     *  - Discards any element whose cleaned character count is 25 or greater
     *
     * Sorting:
     *  - Case-insensitive quicksort in descending order
     *
     * @param input the raw array of name strings
     * @return a new array of cleaned names sorted in descending order (case-insensitive)
     */
    public static String[] cleanAndSortNames(String[] input) {
        List<String> cleaned = new ArrayList<>();

        for (String raw : input) {
            String cleanedName = cleanName(raw);
            if (!cleanedName.isEmpty() && cleanedName.length() < 25) {
                cleaned.add(cleanedName);
            }
        }

        String[] result = cleaned.toArray(new String[0]);
        quickSort(result, 0, result.length - 1);
        return result;
    }

    /**
     * Strips all non-alphabetic characters from a string,
     * leaving only letters (no digits, symbols, or spaces).
     */
    private static String cleanName(String name) {
        StringBuilder sb = new StringBuilder();
        for (char c : name.toCharArray()) {
            if (Character.isLetter(c)) {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private static void quickSort(String[] arr, int low, int high) {
        if (low < high) {
            int pivotIndex = partition(arr, low, high);
            quickSort(arr, low, pivotIndex - 1);
            quickSort(arr, pivotIndex + 1, high);
        }
    }

    private static int partition(String[] arr, int low, int high) {
        String pivot = arr[high];
        int i = low - 1;

        for (int j = low; j < high; j++) {
            // Descending order: elements greater than pivot (case-insensitive) go first
            if (arr[j].compareToIgnoreCase(pivot) > 0) {
                i++;
                swap(arr, i, j);
            }
        }
        swap(arr, i + 1, high);
        return i + 1;
    }

    private static void swap(String[] arr, int i, int j) {
        String temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        String[] input = {"jo9hn", "!S te4ven", "K33im", "All&y", "ABCDEFGHIJKLMNOPQRSTUVWXYZ"};

        String[] result = cleanAndSortNames(input);

        for (String name : result) {
            System.out.println(name);
        }
        // Expected output:
        // Steven
        // Kim
        // john
        // Ally
    }
}
```

**How it matches the example:**
- `jo9hn` → `john`
- `!S te4ven` → `Steven`
- `K33im` → `Kim`
- `All&y` → `Ally`
- `ABCDEFGHIJKLMNOPQRSTUVWXYZ` → 26 letters → length not less than 25 → **removed**

Sorted descending (case-insensitive): `Steven, Kim, john, Ally` ✅ matches your expected output.

**Notes on implementation choices:**
- `Character.isLetter()` is used instead of a regex range check (`a-zA-Z`) so it correctly handles only alphabetic characters as required, while still working predictably for standard ASCII names.
- Elements that become empty after cleaning (e.g., an all-numeric/symbol string) are dropped, since they'd no longer represent a valid name.
- Quicksort remains implemented manually (Lomuto partition scheme) — no `.sort()`/`Arrays.sort()`/`Collections.sort()` used.

